#!/usr/bin/env python3
"""Compute ground truth for CSX-070_Q1."""

from __future__ import annotations

import json
import re
from datetime import date
from decimal import Decimal, ROUND_HALF_UP
from html.parser import HTMLParser
from pathlib import Path


TASK_ID = "CSX-070_Q1"
EVENT_ID = "CSX-070"

ANCHOR_PATH = "data/event_reports/event_reports_003_Locked_event_anchor_April_2024_UAE_and_Dubai_record_rainfall_flood.json"
NASA_REPORT_PATH = "data/event_reports/event_reports_004_01_Locked_package_evidence_report.html.html"
JAXA_REPORT_PATH = "data/event_reports/event_reports_005_03_JAXA_GSMaP_quick_report_-_UAE_extreme_heavy_rainfall.html.html"
GPM_PATH = "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json"
CHIRPS_PATH = "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json"
ERA5_PATH = "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json"


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []
        self.skip_depth = 0

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in {"script", "style"}:
            self.skip_depth += 1
        if tag in {"p", "h1", "h2", "h3", "figcaption", "li"} and not self.skip_depth:
            self.parts.append("\n")

    def handle_endtag(self, tag: str) -> None:
        if tag in {"script", "style"} and self.skip_depth:
            self.skip_depth -= 1

    def handle_data(self, data: str) -> None:
        if self.skip_depth:
            return
        text = " ".join(data.split())
        if text:
            self.parts.append(text)

    def text(self) -> str:
        return " ".join(self.parts)


def load_json(package_dir: Path, relative_path: str) -> dict:
    with (package_dir / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_html_text(package_dir: Path, relative_path: str) -> str:
    parser = TextExtractor()
    parser.feed((package_dir / relative_path).read_text(encoding="utf-8", errors="replace"))
    return parser.text()


def first_float(pattern: str, text: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"missing expected numeric pattern: {pattern}")
    return float(match.group(1).replace(",", ""))


def event_days_inclusive(window: dict) -> int:
    start = date.fromisoformat(window["start_date"])
    end = date.fromisoformat(window["end_date"])
    return (end - start).days + 1


def multiply_round_half_up(value: float, factor: float, places: int) -> float:
    quantum = Decimal("1").scaleb(-places)
    product = Decimal(str(value)) * Decimal(str(factor))
    return float(product.quantize(quantum, rounding=ROUND_HALF_UP))


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    workspace_root = task_dir.parents[2]
    package_dir = workspace_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

    anchor = load_json(package_dir, ANCHOR_PATH)
    nasa_text = read_html_text(package_dir, NASA_REPORT_PATH)
    jaxa_text = read_html_text(package_dir, JAXA_REPORT_PATH)
    gpm = load_json(package_dir, GPM_PATH)
    chirps = load_json(package_dir, CHIRPS_PATH)
    era5 = load_json(package_dir, ERA5_PATH)

    airport_mm = first_float(r"Dubai International Airport[^.]*recorded\s+([0-9.]+)\s+millimeters", nasa_text)
    eastern_mm = first_float(r"up to\s+([0-9.]+)\s+millimeters", nasa_text)
    annual_low_mm = first_float(r"receives only about\s+([0-9.]+)\s+to\s+[0-9.]+\s+millimeters", nasa_text)
    annual_high_mm = first_float(r"receives only about\s+[0-9.]+\s+to\s+([0-9.]+)\s+millimeters", nasa_text)
    report_threshold_mm = first_float(r"more than\s+([0-9.]+)\s+mm of rainfall", jaxa_text)

    gridded_maxima = {
        "GPM_IMERG": round(gpm["stats"]["gpm_event_precip_mm_max"], 2),
        "CHIRPS": round(chirps["stats"]["chirps_event_precip_mm_max"], 2),
        "ERA5_Land": round(era5["stats"]["precipitation_sum_mm_max"], 2),
    }
    highest_grid_source, highest_grid_mm = max(gridded_maxima.items(), key=lambda item: item[1])

    runoff_coefficient = 0.15
    annual_mid_mm = round((annual_low_mm + annual_high_mm) / 2, 1)
    airport_runoff_mm = multiply_round_half_up(airport_mm, runoff_coefficient, 1)
    eastern_runoff_mm = multiply_round_half_up(eastern_mm, runoff_coefficient, 1)
    airport_annual_share = round(airport_mm / annual_mid_mm, 2)
    eastern_annual_share = round(eastern_mm / annual_mid_mm, 2)
    grid_ratio = round(highest_grid_mm / report_threshold_mm, 3)
    runoff_threshold_mm = round(report_threshold_mm * runoff_coefficient, 1)

    threshold_result = "reported_runoff_threshold_crossed_grid_peak_lower"
    primary_gt = {
        "airport_runoff_mm": airport_runoff_mm,
        "eastern_runoff_mm": eastern_runoff_mm,
        "airport_annual_share": airport_annual_share,
        "eastern_annual_share": eastern_annual_share,
        "grid_max_to_report_threshold": grid_ratio,
        "threshold_result": threshold_result,
    }

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "rainfall_runoff_diagnostic",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "event_window": {
                "start_date": anchor["temporal_window"]["start_date"],
                "end_date": anchor["temporal_window"]["end_date"],
                "days_inclusive": event_days_inclusive(anchor["temporal_window"]),
            },
            "rainfall_mm": {
                "dubai_airport_apr16": airport_mm,
                "eastern_uae_less_than_24h": eastern_mm,
                "typical_annual_low": annual_low_mm,
                "typical_annual_high": annual_high_mm,
                "typical_annual_mid": annual_mid_mm,
                "single_day_report_threshold": report_threshold_mm,
            },
            "gridded_event_max_mm": {
                "values": gridded_maxima,
                "highest_source": highest_grid_source,
                "highest_value": highest_grid_mm,
            },
            "decision_rule": {
                "runoff_coefficient": runoff_coefficient,
                "rainfall_threshold_mm": report_threshold_mm,
                "runoff_threshold_mm": runoff_threshold_mm,
                "grid_ratio_below_threshold_if_lt": 1.0,
                "runoff_rounding": "round_half_up_to_one_decimal",
                "canonical_threshold_result": threshold_result,
            },
            "tolerances": {
                "runoff_mm": 0.1,
                "annual_share": 0.01,
                "grid_ratio": 0.001,
                "rainfall_mm": 1.0,
            },
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "final_json_and_label",
                    "points": 4,
                    "description": "Returns all six requested JSON fields and the exact threshold label.",
                    "partial_credit": "Award 2 points for an equivalent label with one numeric omission, or 1 point for a mostly correct label with an incomplete JSON object.",
                },
                {
                    "name": "report_rainfall_anchors",
                    "points": 4,
                    "description": "Extracts 119 mm, 250 mm, the 140-200 mm annual range, and the 170 mm midpoint.",
                    "partial_credit": "Award 2-3 points for three correct anchors, or 1 point for only one or two correct anchors.",
                },
                {
                    "name": "runoff_and_annual_share_arithmetic",
                    "points": 4,
                    "description": "Computes 17.9 mm, 37.5 mm, 0.70, and 1.47 using the stated coefficient and annual midpoint.",
                    "partial_credit": "Award 2-3 points for correct formulas with minor rounding errors, or 1 point for applying the coefficient to only one rainfall anchor.",
                },
                {
                    "name": "gridded_maximum_ratio",
                    "points": 3,
                    "description": "Identifies 56.76 mm as the highest gridded event maximum and computes 0.568 against the 100 mm threshold.",
                    "partial_credit": "Award 2 points for the right source value with wrong rounding, or 1 point for comparing a lower gridded value to the threshold.",
                },
                {
                    "name": "threshold_logic",
                    "points": 3,
                    "description": "Explains that both report rainfall anchors exceed the 100 mm / 15 mm runoff-equivalent threshold while the gridded maximum remains below 100 mm.",
                    "partial_credit": "Award 2 points if one side of the threshold logic is correct, or 1 point if the comparison direction is right but values are missing.",
                },
                {
                    "name": "computed_interpretation",
                    "points": 2,
                    "description": "Provides a concise interpretation tied to the computed diagnostic without adding extra loss or depth claims.",
                    "partial_credit": "Award 1 point for a reasonable but wordy interpretation or for omitting one important numeric link.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                ANCHOR_PATH,
                NASA_REPORT_PATH,
                JAXA_REPORT_PATH,
                GPM_PATH,
                CHIRPS_PATH,
                ERA5_PATH,
            ],
        },
    }

    with (task_dir / "computed_gt.json").open("w", encoding="utf-8") as handle:
        json.dump(computed_gt, handle, indent=2, sort_keys=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
